package app.flare.auto;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
public final class DockEditorActivity extends Activity {
 UiKit ui;SharedPreferences prefs;ArrayList<DockConfig.Item> items;LinearLayout list,group,add,sizeRow,labelsRow,monoRow;int choosing=-1;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);ui=new UiKit(this);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(ui.t.background));prefs=getSharedPreferences("home",0);items=DockConfig.read(prefs);if(b!=null)choosing=b.getInt("choosing",-1);render();}
 @Override protected void onSaveInstanceState(Bundle out){out.putInt("choosing",choosing);super.onSaveInstanceState(out);}
 void render(){LinearLayout root=ui.column();root.setBackgroundColor(ui.t.background);root.addView(ui.header("Dock configuration"),new LinearLayout.LayoutParams(-1,ui.dp(56)));ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list=ui.column();list.setPadding(ui.dp(16),0,ui.dp(16),ui.dp(20));scroll.addView(list);setContentView(root);group=ui.group();list.addView(group);populateRows();
 LinearLayout actions=ui.group();list.addView(ui.section("APPEARANCE"));list.addView(actions);add=ui.valueRow("Add shortcut","",()->{items.add(items.size()-1,new DockConfig.Item(0,"",true));save();});ui.add(actions,add);sizeRow=ui.valueRow("Icon scale",sizeName(),()->new ThemedDialogs.Builder(this).setTitle("Icon scale").setItems(new String[]{"Small","Medium","Large"},(d,n)->{prefs.edit().putInt("dock_icons",new int[]{20,26,32}[n]).apply();((TextView)sizeRow.getChildAt(1)).setText(sizeName());}).show());ui.add(actions,sizeRow);labelsRow=ui.toggle("Show labels",prefs.getBoolean("dock_labels",true),()->{boolean enabled=!prefs.getBoolean("dock_labels",true);prefs.edit().putBoolean("dock_labels",enabled).apply();((TextView)labelsRow.getChildAt(1)).setText(enabled?"On":"Off");});ui.add(actions,labelsRow);monoRow=ui.toggle("Monochrome app icons",prefs.getBoolean("dock_mono",false),()->{boolean enabled=!prefs.getBoolean("dock_mono",false);prefs.edit().putBoolean("dock_mono",enabled).apply();((TextView)monoRow.getChildAt(1)).setText(enabled?"On":"Off");});ui.add(actions,monoRow);ui.add(actions,ui.valueRow("Restore default shortcuts","",()->new ThemedDialogs.Builder(this).setTitle("Restore default shortcuts?").setPositiveButton("Restore",(d,w)->{prefs.edit().remove(DockConfig.KEY).remove("dock_order").apply();items=DockConfig.read(prefs);populateRows();updateOptions();}).setNegativeButton("Cancel",null).show()));updateOptions();}
 void populateRows(){group.removeAllViews();for(int n=0;n<items.size();n++){final int index=n;DockConfig.Item item=items.get(n);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(ui.dp(56));if(!item.visible)row.setAlpha(.45f);LinearLayout identity=new LinearLayout(this);identity.setGravity(Gravity.CENTER_VERTICAL);identity.setPadding(ui.dp(12),0,0,0);View icon;if(item.type==5){ImageView app=new ImageView(this);try{app.setImageDrawable(getPackageManager().getActivityIcon(ComponentName.unflattenFromString(item.target)));}catch(Exception ignored){}icon=app;}else icon=new HomeActivity.NavIcon(this,DockConfig.ICONS[item.type],ui.t.textPrimary);identity.addView(icon,new LinearLayout.LayoutParams(ui.dp(28),ui.dp(28)));TextView name=ui.text(DockConfig.name(this,item),16,ui.t.textPrimary);name.setPadding(ui.dp(10),0,0,0);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);identity.addView(name,new LinearLayout.LayoutParams(0,ui.dp(56),1));row.addView(identity,new LinearLayout.LayoutParams(0,ui.dp(56),1));if(item.type!=4)identity.setOnClickListener(v->choose(index));button(row,"↑",index>0,()->{Collections.swap(items,index,index-1);save();});button(row,"↓",index<items.size()-1,()->{Collections.swap(items,index,index+1);save();});button(row,item.visible?"◉":"○",item.type!=4,()->{item.visible=!item.visible;row.setAlpha(item.visible?1f:.45f);((TextView)row.getChildAt(3)).setText(item.visible?"◉":"○");DockConfig.save(prefs,items);});button(row,"×",item.type!=4,()->{items.remove(index);save();});ui.add(group,row);}
 }
 void updateOptions(){((TextView)add.getChildAt(1)).setText(items.size()+" / "+DockConfig.maxSlots(this));boolean canAdd=items.size()<DockConfig.maxSlots(this);add.setEnabled(canAdd);add.setAlpha(canAdd?1f:.45f);((TextView)sizeRow.getChildAt(1)).setText(sizeName());((TextView)labelsRow.getChildAt(1)).setText(prefs.getBoolean("dock_labels",true)?"On":"Off");((TextView)monoRow.getChildAt(1)).setText(prefs.getBoolean("dock_mono",false)?"On":"Off");}

 String sizeName(){int n=prefs.getInt("dock_icons",24);return n<23?"Small":n<30?"Medium":"Large";}
 void button(LinearLayout row,String label,boolean enabled,Runnable action){TextView b=ui.text(label,22,ui.t.textPrimary);b.setGravity(Gravity.CENTER);b.setVisibility(enabled?View.VISIBLE:View.INVISIBLE);row.addView(b,new LinearLayout.LayoutParams(ui.dp(56),ui.dp(56)));if(enabled)b.setOnClickListener(v->action.run());}
 void choose(int i){choosing=i;String[] choices={"Audio","Radio","Bluetooth","Screen off","Apps","Application"};new ThemedDialogs.Builder(this).setTitle("Shortcut action").setItems(choices,(d,n)->{if(n==4){Toast.makeText(this,"Apps already has a permanent shortcut",Toast.LENGTH_SHORT).show();return;}if(n==5){startActivityForResult(new Intent(this,AppPickerActivity.class).putExtra(AppPickerActivity.ROLE,"dock").putExtra(AppPickerActivity.TARGET,items.get(i).target),1);}else{items.set(i,new DockConfig.Item(n,"",true));save();}}).show();}
 void save(){DockConfig.save(prefs,items);populateRows();updateOptions();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null&&choosing>=0&&choosing<items.size()){String target=data.getStringExtra(AppPickerActivity.TARGET);if(target!=null&&!target.isEmpty()){items.set(choosing,new DockConfig.Item(5,target,true));save();}}}
}
